import{_ as t,o as a,c as o,a3 as c}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"CMake API","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"CMake API | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/cmake-api"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/cmake-api"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/cmake-api"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/reference/cmake-api"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/cmake-api"}]]},"headers":[],"relativePath":"xclang/reference/cmake-api.md","filePath":"en/xclang/reference/cmake-api.md","lastUpdated":1791227177000}'),d={name:"xclang/reference/cmake-api.md"};function i(n,e,s,l,r,h){return a(),o("div",null,[...e[0]||(e[0]=[c(`<h1 id="cmake-api" tabindex="-1">CMake API <a class="header-anchor" href="#cmake-api" aria-label="Permalink to &quot;CMake API&quot;">​</a></h1><p>Everything xclang&#39;s CMake package defines. How to use it is <a href="./../integrations/cmake">CMake</a>; this page is the list.</p><p>The package is <code>lib/cmake/xclang</code> of every toolchain archive from 23.1.2.6 on (and so of the conda package), and <code>packages/cmake/</code> of the repository at every tag from 23.1.2.6 on. It needs CMake 3.28 or later and, for C++20 modules, the Ninja or Ninja Multi-Config generator with Ninja 1.11 or later.</p><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>file</th><th>what it is</th></tr></thead><tbody><tr><td><code>xclang-config.cmake</code></td><td><code>find_package(xclang)</code>: <code>xclang::std</code>, <code>xclang_add_std()</code>, <code>xclang_debug_symbols()</code>, <code>XCLANG_ROOT</code>, the ThinLTO cache</td></tr><tr><td><code>xclang-config-version.cmake</code></td><td>the release, for <code>find_package(xclang 23.1)</code> (toolchain archives only)</td></tr><tr><td><code>toolchain.cmake</code></td><td>the tree as a build&#39;s toolchain, for the host or <code>XCLANG_TARGET</code></td></tr><tr><td><code>xclang.cmake</code></td><td>in <code>packages/cmake/</code> only: included before <code>project()</code> from a FetchContent checkout, downloads the toolchain</td></tr></tbody></table><h2 id="find-package-xclang" tabindex="-1">find_package(xclang) <a class="header-anchor" href="#find-package-xclang" aria-label="Permalink to &quot;find_package(xclang)&quot;">​</a></h2><p>Comes after <code>project()</code> (or <code>enable_language(CXX)</code>), whose C++ compiler must be xclang&#39;s <code>clang++</code>. It finds the package through <code>PATH</code> (<code>&lt;xclang&gt;/bin</code> gives <code>&lt;xclang&gt;/lib/cmake/xclang</code>), <code>xclang_ROOT</code>, or <code>CMAKE_PREFIX_PATH</code>.</p><table tabindex="0"><thead><tr><th>name</th><th>kind</th><th></th></tr></thead><tbody><tr><td><code>xclang::std</code></td><td>target</td><td>static library of libc++&#39;s <code>std</code> and <code>std.compat</code> modules, built for the build&#39;s target with the language options of the directory that called <code>find_package(xclang)</code>, as they are at the end of its <code>CMakeLists.txt</code>; built only when something links it</td></tr><tr><td><code>xclang_add_std(&lt;name&gt;)</code></td><td>function</td><td>another such library; options given to it with <code>PUBLIC</code> reach its importers</td></tr><tr><td><code>xclang_debug_symbols(&lt;target&gt; [GSYM_ARGS &lt;option&gt;...])</code></td><td>function</td><td>after each link of <code>&lt;target&gt;</code>: <code>&lt;target&gt;.gsym</code> next to the program (llvm-gsymutil&#39;s output in <code>&lt;target&gt;.gsym.log</code>), and for a macOS target <code>&lt;target&gt;.dSYM</code> first</td></tr><tr><td><code>XCLANG_ROOT</code></td><td>variable</td><td>the toolchain&#39;s directory</td></tr><tr><td><code>XCLANG_THINLTO_CACHE</code></td><td>cache variable</td><td>an absolute directory for the linker&#39;s ThinLTO cache; set, it is made at configure time and every link of the calling directory and its subdirectories gets the target&#39;s linker&#39;s flag. Its first value comes from the environment variable of the same name</td></tr></tbody></table><p><code>xclang::std</code> asks its importers for C++23, or for the <code>CMAKE_CXX_STANDARD</code> it was built with if that is 20 or later.</p><h2 id="toolchain-cmake" tabindex="-1">toolchain.cmake <a class="header-anchor" href="#toolchain-cmake" aria-label="Permalink to &quot;toolchain.cmake&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -G</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ninja</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --toolchain</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">xclan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/lib/cmake/xclang/toolchain.cmake</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-DXCLANG_TARGET=&lt;triple&gt;]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>variable</th><th></th></tr></thead><tbody><tr><td><code>XCLANG_TARGET</code></td><td><code>x86_64-unknown-linux-gnu</code>, <code>aarch64-unknown-linux-gnu</code>, <code>x86_64-w64-mingw32</code>, <code>aarch64-w64-mingw32</code>, <code>aarch64-apple-darwin</code> or <code>x86_64-apple-darwin</code>; the host&#39;s by default. macOS targets build on macOS only</td></tr><tr><td><code>XCLANG_ROOT</code></td><td>the tree, when the file is used from outside one</td></tr></tbody></table><p>It sets the C, C++ and ASM compilers and the binary tools to the tree&#39;s: <code>llvm-ar</code>, <code>llvm-ranlib</code>, <code>llvm-nm</code>, <code>llvm-objcopy</code>, <code>llvm-objdump</code>, <code>llvm-readelf</code>, <code>llvm-strip</code>, <code>llvm-addr2line</code>, <code>llvm-dlltool</code>; for Windows targets <code>llvm-windres</code> as the RC compiler; for macOS targets <code>llvm-libtool-darwin</code>, <code>llvm-lipo</code> and <code>llvm-install-name-tool</code> (Apple&#39;s <code>libtool</code> cannot read the bitcode of a newer LLVM).</p><p>For a Linux or Windows target other than the host it also sets <code>CMAKE_SYSTEM_NAME</code>, <code>CMAKE_SYSTEM_PROCESSOR</code>, <code>CMAKE_&lt;LANG&gt;_COMPILER_TARGET</code>, <code>CMAKE_SYSROOT</code> (the target&#39;s directory) and <code>CMAKE_FIND_ROOT_PATH_MODE_{LIBRARY,INCLUDE,PACKAGE}</code> to <code>ONLY</code>, so libraries, headers and packages are looked for in that directory alone (programs on the build machine). The other macOS architecture is <code>CMAKE_OSX_ARCHITECTURES</code>, which CMake does not treat as cross-compiling. Sysroot, C++ library, runtimes and linker come from the target&#39;s config file, not from this file.</p><h2 id="xclang-cmake" tabindex="-1">xclang.cmake <a class="header-anchor" href="#xclang-cmake" aria-label="Permalink to &quot;xclang.cmake&quot;">​</a></h2><p>Included before <code>project()</code>, from a checkout of a release&#39;s tag:</p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(XCLANG_VERSION 23.1.2.6)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(FetchContent)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FetchContent_Declare(xclang</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    GIT_REPOSITORY https://github.com/clice-io/xclang</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    GIT_TAG </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\${XCLANG_VERSION}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FetchContent_MakeAvailable(xclang)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\${xclang_SOURCE_DIR}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/packages/cmake/xclang.cmake)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>variable</th><th></th></tr></thead><tbody><tr><td><code>XCLANG_VERSION</code></td><td>the release to download; without it, the release tagging the checkout</td></tr><tr><td><code>XCLANG_TARGET</code></td><td>another target to build for (<code>toolchain.cmake</code>)</td></tr><tr><td><code>XCLANG_ROOT</code></td><td>an unpacked xclang to use instead of downloading one</td></tr><tr><td><code>XCLANG_CACHE_DIR</code></td><td>where toolchains are unpacked, <code>&lt;version&gt;/&lt;host&gt;</code> each (also an environment variable); by default <code>$XDG_CACHE_HOME/xclang</code> or <code>~/.cache/xclang</code>, <code>~/Library/Caches/xclang</code> on macOS, <code>%LOCALAPPDATA%\\xclang</code> on Windows</td></tr><tr><td><code>XCLANG_URL</code></td><td>where <code>SHA256SUMS</code> and the archives are downloaded from, a mirror of the release; its <code>SHA256SUMS</code> is then the one trusted</td></tr></tbody></table><p>It downloads the release&#39;s <code>SHA256SUMS</code> and the host&#39;s <code>xclang-&lt;version&gt;-&lt;host&gt;.tar.xz</code>, checks the archive against its line, unpacks it aside and moves it into the cache (so build trees configured at once do not clash), and sets <code>CMAKE_TOOLCHAIN_FILE</code>. It stops if the build already has a toolchain file (vcpkg&#39;s, say): vcpkg chain-loads xclang&#39;s instead (<code>VCPKG_CHAINLOAD_TOOLCHAIN_FILE</code>).</p><h2 id="libclang-s-package" tabindex="-1">libclang&#39;s package <a class="header-anchor" href="#libclang-s-package" aria-label="Permalink to &quot;libclang&#39;s package&quot;">​</a></h2><p>The libclang archives carry LLVM&#39;s and clang&#39;s own CMake packages (<code>find_package(Clang)</code>), and <code>lib/cmake/xclang/libclang.cmake</code>, which records the build: <code>XCLANG_LLVM_VERSION</code>, <code>XCLANG_LTO</code>, <code>XCLANG_PGO</code>, <code>XCLANG_PATCHES</code> and the like. See <a href="./../features/libclang">libclang</a>.</p>`,21)])])}const k=t(d,[["render",i]]);export{p as __pageData,k as default};
